-- Arbeitsrecht Berufsbildung > Wirtschaftliche Zusammenhänge > Wirtschaftliche Trends > Digitalisierungseffekte
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Führt die Digitalisierung in einem IT-Betrieb zu einer erhöhten Effizienz?', 2, '[{"text": "Ja", "correct": true, "because": "Digitalisierung automatisiert Prozesse"}, {"text": "Nein", "correct": false, "because": "Effizienz ist ein Effekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann die Digitalisierung die Kosten eines IT-Betriebs senken?', 2, '[{"text": "Ja", "correct": true, "because": "Automatisierung reduziert Arbeitskosten"}, {"text": "Nein", "correct": false, "because": "Kostensenkung ist möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Erhöht die Digitalisierung den Bedarf an IT-Fachkräften in einem IT-Betrieb?', 2, '[{"text": "Ja", "correct": true, "because": "Digitale Systeme erfordern Fachwissen"}, {"text": "Nein", "correct": false, "because": "Fachkräftebedarf steigt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind Digitalisierungseffekte für einen IT-Betrieb mit Risiken wie Datenschutz verbunden?', 2, '[{"text": "Ja", "correct": true, "because": "Digitalisierung bringt Datenschutzrisiken"}, {"text": "Nein", "correct": false, "because": "Datenschutz ist ein Risiko"}]'),
('00000000-0000-0000-0000-000000000000', 'Ermöglicht die Digitalisierung einem IT-Betrieb den Zugang zu globalen Märkten?', 2, '[{"text": "Ja", "correct": true, "because": "Digitale Plattformen erweitern Märkte"}, {"text": "Nein", "correct": false, "because": "Globalisierung wird gefördert"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welcher Digitalisierungseffekt ist für einen IT-Betrieb am bedeutendsten?', 2, '[{"text": "Prozessautomatisierung", "correct": true, "because": "Steigert Effizienz"}, {"text": "Höhere Steuerlast", "correct": false, "because": "Kein direkter Effekt"}, {"text": "Weniger Innovation", "correct": false, "because": "Innovation wird gefördert"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein typischer Vorteil der Digitalisierung für einen IT-Betrieb?', 3, '[{"text": "Kostensenkung durch Automatisierung", "correct": true, "because": "Reduziert Arbeitskosten"}, {"text": "Geringere Marktgröße", "correct": false, "because": "Märkte wachsen"}, {"text": "Höhere manuelle Arbeit", "correct": false, "because": "Automatisierung verringert Arbeit"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Nachteil kann durch Digitalisierungseffekte in einem IT-Betrieb entstehen?', 3, '[{"text": "Cybersecurity-Risiken", "correct": true, "because": "Digitale Systeme sind anfällig"}, {"text": "Geringere Effizienz", "correct": false, "because": "Effizienz steigt"}, {"text": "Weniger Kunden", "correct": false, "because": "Kundenbasis wächst"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Technologie fördert die Digitalisierungseffekte eines IT-Betriebs?', 2, '[{"text": "Cloud Computing", "correct": true, "because": "Ermöglicht flexible Prozesse"}, {"text": "Manuelle Datenverarbeitung", "correct": false, "because": "Nicht digital"}, {"text": "Lokale Server", "correct": false, "because": "Weniger flexibel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welchen Einfluss hat die Digitalisierung auf die Geschäftsmodelle eines IT-Betriebs?', 3, '[{"text": "Ermöglicht neue digitale Geschäftsmodelle", "correct": true, "because": "Z. B. SaaS-Modelle"}, {"text": "Reduziert Innovation", "correct": false, "because": "Innovation wird gefördert"}, {"text": "Erhöht lokale Abhängigkeit", "correct": false, "because": "Globalität steigt"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bieten Digitalisierungseffekte einem IT-Betrieb?', 4, '[{"text": "Erhöhte Effizienz", "correct": true, "because": "Automatisierung steigert Effizienz"}, {"text": "Kostensenkung", "correct": true, "because": "Weniger manuelle Arbeit"}, {"text": "Geringerer Wettbewerb", "correct": false, "because": "Wettbewerb steigt"}, {"text": "Zugang zu globalen Märkten", "correct": true, "because": "Digitale Plattformen erweitern Reichweite"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile können Digitalisierungseffekte einem IT-Betrieb bringen?', 3, '[{"text": "Cybersecurity-Risiken", "correct": true, "because": "Digitale Systeme sind anfällig"}, {"text": "Datenschutzprobleme", "correct": true, "because": "Datenverarbeitung birgt Risiken"}, {"text": "Geringere Kosten", "correct": false, "because": "Kosten können sinken"}, {"text": "Erhöhter Bedarf an Fachkräften", "correct": true, "because": "Fachwissen wird benötigt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Effekte hat die Digitalisierung auf die Arbeitsweise eines IT-Betriebs?', 4, '[{"text": "Automatisierung von Prozessen", "correct": true, "because": "Reduziert manuelle Arbeit"}, {"text": "Verbesserte Kommunikation", "correct": true, "because": "Digitale Tools fördern Austausch"}, {"text": "Höhere manuelle Arbeit", "correct": false, "because": "Manuelle Arbeit sinkt"}, {"text": "Flexiblere Arbeitsmodelle", "correct": true, "because": "Remote-Arbeit wird ermöglicht"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Technologien verstärken die Digitalisierungseffekte eines IT-Betriebs?', 3, '[{"text": "Cloud Computing", "correct": true, "because": "Flexibilität und Skalierbarkeit"}, {"text": "Künstliche Intelligenz", "correct": true, "because": "Automatisiert Prozesse"}, {"text": "Manuelle Datenbanken", "correct": false, "because": "Nicht digital effizient"}, {"text": "Internet of Things", "correct": true, "because": "Vernetzt Geräte"}]'),
('00000000-0000-0000-0000-000000000000', 'Was unterscheidet die Digitalisierungseffekte eines IT-Betriebs von denen eines Nicht-IT-Betriebs?', 3, '[{"text": "IT-Betriebe nutzen Digitalisierung direkt", "correct": true, "because": "Kernkompetenz ist digital"}, {"text": "IT-Betriebe haben größeren Nutzen", "correct": true, "because": "Direkte Anwendung"}, {"text": "Nicht-IT-Betriebe sind effizienter", "correct": false, "because": "IT-Betriebe profitieren stärker"}, {"text": "IT-Betriebe haben höhere Risiken", "correct": true, "because": "Cybersecurity stärker betroffen"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Digitalisierung erhöht die Effizienz eines IT-Betriebs. b) Digitalisierung führt zu geringeren Kosten.', 3, '[{"text": "Nur a) stimmt", "correct": false, "because": "Beides ist richtig"}, {"text": "Beides stimmt", "correct": true, "because": "Effizienz und Kostensenkung sind Effekte"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "Beides ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Digitalisierungseffekte erhöhen den Bedarf an IT-Fachkräften. b) Digitalisierung birgt keine Cybersecurity-Risiken.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Fachkräfte ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Digitalisierung ermöglicht globale Märkte für einen IT-Betrieb. b) Digitalisierung reduziert den Verwaltungsaufwand.', 3, '[{"text": "Nur a) stimmt", "correct": false, "because": "Beides ist richtig"}, {"text": "Beides stimmt", "correct": true, "because": "Globale Märkte und weniger Aufwand"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "Beides ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Digitalisierung fördert neue Geschäftsmodelle in einem IT-Betrieb. b) Digitalisierung erhöht manuelle Arbeit.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Geschäftsmodelle ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Digitalisierungseffekte erhöhen die Wettbewerbsfähigkeit eines IT-Betriebs. b) Digitalisierung hat keine Auswirkungen auf die Kundenbasis.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Wettbewerbsfähigkeit ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

